import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String transcript = next();
        int m = transcript.length();
        // board lives in cells[lo..hi) of a buffer with room to grow on both sides
        char[] cells = new char[2 * m + 4];
        int lo = m + 1, hi = m + 3;
        cells[lo] = 'B';
        cells[lo + 1] = 'W';
        for (int turn = 0; turn < m; turn++) {
            char color = turn % 2 == 0 ? 'B' : 'W';
            if (transcript.charAt(turn) == 'L') {
                cells[--lo] = color;
                int target = lo + 1;
                while (target < hi && cells[target] != color) target++;
                if (target < hi) // flip everything between the new tile and the nearest same color
                    for (int i = lo + 1; i < target; i++) cells[i] = color;
            } else {
                cells[hi++] = color;
                int target = hi - 2;
                while (target >= lo && cells[target] != color) target--;
                if (target >= lo)
                    for (int i = target + 1; i < hi - 1; i++) cells[i] = color;
            }
        }
        int black = 0;
        for (int i = lo; i < hi; i++) if (cells[i] == 'B') black++;
        System.out.println(black + " " + (hi - lo - black));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	transcript := next()
	m := len(transcript)
	// board lives in cells[lo:hi] of a buffer with room to grow on both sides
	cells := make([]byte, 2*m+4)
	lo, hi := m+1, m+3
	cells[lo], cells[lo+1] = 'B', 'W'
	for turn := 0; turn < m; turn++ {
		color := byte('B')
		if turn%2 == 1 {
			color = 'W'
		}
		if transcript[turn] == 'L' {
			lo--
			cells[lo] = color
			target := lo + 1
			for target < hi && cells[target] != color {
				target++
			}
			if target < hi { // flip everything between the new tile and the nearest same color
				for i := lo + 1; i < target; i++ {
					cells[i] = color
				}
			}
		} else {
			cells[hi] = color
			hi++
			target := hi - 2
			for target >= lo && cells[target] != color {
				target--
			}
			if target >= lo {
				for i := target + 1; i < hi-1; i++ {
					cells[i] = color
				}
			}
		}
	}
	black := 0
	for _, c := range cells[lo:hi] {
		if c == 'B' {
			black++
		}
	}
	fmt.Println(black, hi-lo-black)
}
